    @Test
    fun packageMatching_doesNotFalsePositiveOnSharedPrefix() {
        val sharedPrefixDump =
            """
            SPF Nodes:
            Node Root (stateIndex=0, z=0) id=1:
              Node space-root-task-1 (stateIndex=0, z=0) id=10:
                Node com.example.app.pro/com.example.app.pro.MainActivity#101 (stateIndex=0, z=0) id=11:
                  ImpNodeWorldPosition=(1.000 1.000 1.000)
              Node space-root-task-2 (stateIndex=0, z=0) id=20:
                Node com.example.app/com.example.app.MainActivity#102 (stateIndex=0, z=0) id=21:
                  ImpNodeWorldPosition=(2.000 2.000 2.000)
            """
                .trimIndent()

        val scene = SpatialSceneHelper.parseSpatialScene(sharedPrefixDump)

        // Matching com.example.app should find only task 2 / window 21, not com.example.app.pro
        val baseAppTask = assertNotNull(scene.findTaskByPackageName("com.example.app"))
        val baseAppNode = assertNotNull(baseAppTask.findNode { it.name.contains("MainActivity") })
        assertEquals(21, baseAppNode.id)
        assertEquals(Vector3(2.0f, 2.0f, 2.0f), baseAppNode.position)
        assertEquals(20, baseAppTask.activitySpaceRoot.id)

        // Matching com.example.app.pro should find task 1 / window 11
        val proAppTask = assertNotNull(scene.findTaskByPackageName("com.example.app.pro"))
        val proAppNode = assertNotNull(proAppTask.findNode { it.name.contains("MainActivity") })
        assertEquals(11, proAppNode.id)
        assertEquals(Vector3(1.0f, 1.0f, 1.0f), proAppNode.position)
        assertEquals(10, proAppTask.activitySpaceRoot.id)

        // Partial prefix com.example should not match either app
        assertNull(scene.findTaskByPackageName("com.example"))
    }

    @Test
    fun containsPackage_delimiterAndSegmentBoundaryChecks() {
        assertTrue(
            SpatialSceneHelper.containsPackage(
                "Node com.example.app/com.example.app.MainActivity#101",
                "com.example.app",
            )
        )
        assertFalse(
            SpatialSceneHelper.containsPackage(
                "Node com.example.app.pro/com.example.app.pro.MainActivity#101",
                "com.example.app",
            )
        )
        assertFalse(
            SpatialSceneHelper.containsPackage(
                "Node prefix.com.example.app/MainActivity#101",
                "com.example.app",
            )
        )
        assertFalse(
            SpatialSceneHelper.containsPackage(
                "Node com.example.app2/MainActivity#101",
                "com.example.app",
            )
        )
        assertTrue(
            SpatialSceneHelper.containsPackage("Node com.example.app (id=1)", "com.example.app")
        )
        assertFalse(
            SpatialSceneHelper.containsPackage("Node com.example.app (id=1)", "com.example")
        )
    }

