    @Test
    fun spatialNode_worldExtents_extractsProperly() {
        val scene = SpatialSceneHelper.parseSpatialScene(fullSpaceComposeDumpsys)
        val task = assertNotNull(scene.findTaskById(963))
        val panel = assertNotNull(task.findNodeByName("ViewPanel:2"))
        // root2DSurfaceBoundsInMeters is (0.400, 0.400), ImpNodeWorldScale is (2.008, 2.008, 2.008)
        val panelExtents = assertNotNull(panel.worldExtents)
        val panelHalfExtents = assertNotNull(panel.worldHalfExtents)
        assertEquals(0.8032f, panelExtents.x, 1e-3f)
        assertEquals(0.8032f, panelExtents.y, 1e-3f)
        assertEquals(2.008f, panelExtents.z, 1e-3f)
        assertEquals(0.4016f, panelHalfExtents.x, 1e-3f)
        assertEquals(0.4016f, panelHalfExtents.y, 1e-3f)
        assertEquals(1.004f, panelHalfExtents.z, 1e-3f)
        assertEquals(panelExtents / 2f, panelHalfExtents)

        // Leaf collider / input target quad uses its quad scale
        val orbiterCollider = assertNotNull(task.findNodeByName("#251"))
        val colliderExtents = assertNotNull(orbiterCollider.worldExtents)
        assertEquals(Vector3(0.060f, 0.060f, 1.004f), colliderExtents)
        assertEquals(Vector3(0.030f, 0.030f, 0.502f), orbiterCollider.worldHalfExtents)

        // Abstract transform / layout node has no bounds in CPM
        val column = assertNotNull(task.findNodeByName("SpatialColumn"))
        assertNull(column.surfaceBoundsInMeters)
        assertNull(column.worldExtents)
        assertNull(column.worldHalfExtents)
    }

    @Test
    fun spatialNode_equalsHashCodeAndToString() {
