    @Test
    fun spatialNode_childOfHiddenTaskRoot_inheritsHiddenVisibility() {
        val rootNode = SpatialNode(header = "Node Root id=1:", name = "Root", id = 1, depth = 0)
        val hiddenTaskRoot =
            SpatialNode(
                header = "Node space-root-task-77 id=2:",
                name = "space-root-task-77",
