    @Test
    fun spatialScene_cpmStructuralRolesAndSelectors_resolvesCorrectly() {
        val dump =
            """
            Node Root (stateIndex=0) id=1:
              Node space-root-task-1206 (stateIndex=0) id=100:
                Node space-transform-spatial-445 (stateIndex=0) id=101:
                  Node MovableRow (stateIndex=0) id=102:
                  isSysUi=false isAndroid2d=false isAppSpatialEmbeddedWindowLeash=false reformOptions=<enable=1, flags=7>
                    Node MoveHandle#0 (stateIndex=0) id=103:
                    isSysUi=true isAndroid2d=false
                    Node ParentPanelContainer (stateIndex=0) id=104:
                    isSysUi=false isAndroid2d=false isAppSpatialEmbeddedWindowLeash=true reformOptions=<enable=3, flags=7>
                      Node ChildOrbiterA (stateIndex=0) id=105:
                      isSysUi=false isAndroid2d=false isAppSpatialEmbeddedWindowLeash=true
                        Node #8936 (stateIndex=0) id=106:
                        isSysUi=false isAndroid2d=true input-id=8936 buffer=96x96 root2DSurfaceBoundsInMeters=(0.060 0.060) root2DSurfaceBoundsInPixels=(96.000 96.000)
                      Node ChildOrbiterB (stateIndex=0) id=107:
                      isSysUi=false isAndroid2d=false isAppSpatialEmbeddedWindowLeash=true
                        Node #8939 (stateIndex=0) id=108:
                        isSysUi=false isAndroid2d=true input-id=8939 buffer=96x96 root2DSurfaceBoundsInMeters=(0.060 0.060) root2DSurfaceBoundsInPixels=(96.000 96.000)
                      Node #8904 (stateIndex=0) id=109:
                      isSysUi=false isAndroid2d=true input-id=8904 buffer=293x357 root2DSurfaceBoundsInMeters=(0.183 0.223) root2DSurfaceBoundsInPixels=(293.000 357.000)
                      Node ResizeCorner#1 (stateIndex=0) id=110:
                      isSysUi=true isAndroid2d=false
                  Node TaskWindowLeashContainer (stateIndex=0) id=120:
                  isSysUi=false isAndroid2d=false isAppSpatialEmbeddedWindowLeash=false reformOptions=<enable=3, flags=7>
                    Node window-task-1206 (stateIndex=0) id=121:
                    isSysUi=false isAndroid2d=false
                      Node androidx.xr.compose.testapp/SpatialCompose#8933 (stateIndex=0) id=122:
                      isSysUi=false isAndroid2d=true input-id=8933 buffer=1520x1680 root2DSurfaceBoundsInMeters=(0.950 1.050)
                  Node ActivityWindowContainer (stateIndex=0) id=130:
                  isSysUi=false isAndroid2d=false isAppSpatialEmbeddedWindowLeash=false
                    Node task-107191162-window (stateIndex=0) id=131:
                    isSysUi=false isAndroid2d=false
                      Node androidx.xr.compose.testapp/AnotherActivity#8953 (stateIndex=0) id=132:
                      isSysUi=false isAndroid2d=true input-id=8953 buffer=1520x720 root2DSurfaceBoundsInMeters=(0.950 0.450)
                  Node SubspaceNode (stateIndex=0) id=140:
                  isSysUi=false isAndroid2d=false hasSubspace=true
            """
                .trimIndent()

        val scene = SpatialSceneHelper.parseSpatialScene(dump)
        val task = assertNotNull(scene.findTaskById(1206))

        // Task-level structural selectors (no app-imposed or Compose-imposed names needed)
        val taskWindow = assertNotNull(task.taskWindowLeash)
        assertEquals(120, taskWindow.id)
        assertEquals(Vector2(1520f, 1680f), taskWindow.effectiveBufferSize)
        assertEquals(Vector2(0.950f, 1.050f), taskWindow.effectiveSurfaceBoundsInMeters)
        assertEquals(8933, taskWindow.ownInputTarget?.inputId)

        assertEquals(1, task.activityWindowLeashes.size)
        val activityWindow = task.activityWindowLeashes.single()
        assertEquals(130, activityWindow.id)
        assertEquals(Vector2(1520f, 720f), activityWindow.effectiveBufferSize)
        assertEquals(8953, activityWindow.ownInputTarget?.inputId)

        assertEquals(1, task.subspaceNodes.size)
        assertEquals(140, task.subspaceNodes.single().id)

        // Top-level window leashes vs child window leashes
        assertEquals(3, task.topLevelWindowLeashes.size)
        val parentPanel = assertNotNull(task.findNode { it.id == 104 })
        assertTrue(parentPanel.isTopLevelWindowLeash)
        assertEquals(2, parentPanel.childWindowLeashes.size)
        assertEquals(setOf(105, 107), parentPanel.childWindowLeashes.map { it.id }.toSet())

        // Parent panel resolves its own #8904 surface & input target, skipping child orbiters
        // (#8936, #8939)
        assertEquals(109, parentPanel.primarySurfaceNode?.id)
        assertEquals(8904, parentPanel.ownInputTarget?.inputId)
        assertEquals(Vector2(0.183f, 0.223f), parentPanel.effectiveSurfaceBoundsInMeters)
        assertEquals(Vector2(293f, 357f), parentPanel.effectiveBufferSize)

        // Affordance scoping: MovableRow only returns MoveHandle#0, never ResizeCorner#1 from
        // ParentPanelContainer
        val movableRow = assertNotNull(task.findNode { it.id == 102 })
        assertEquals(1, movableRow.moveAffordanceNodes.size)
        assertEquals(103, movableRow.moveAffordanceNodes.single().id)
        assertTrue(movableRow.resizeAffordanceNodes.isEmpty())

        assertEquals(1, parentPanel.resizeAffordanceNodes.size)
        assertEquals(110, parentPanel.resizeAffordanceNodes.single().id)
        assertTrue(parentPanel.moveAffordanceNodes.isEmpty())
    }

    @Test
    fun spatialNode_transformPointToWorld_andFromWorld_withScale() {
        val node =
            SpatialNode(
                name = "test-node",
                attributes =
                    mapOf(
                        "ImpNodeWorldPosition" to floatArrayOf(1.0f, 2.0f, 3.0f),
                        "ImpNodeWorldRotation" to floatArrayOf(0.7071068f, 0.0f, 0.7071068f, 0.0f),
                        "ImpNodeWorldScale" to floatArrayOf(0.5f, 2.0f, 4.0f),
                    ),
            )

        val localPoint = Vector3(1.0f, 1.0f, 1.0f)
        // Scaled local point: (0.5, 2.0, 4.0)
        // 90-degree Y rotation rotates (x, y, z) to (z, y, -x):
        // (4.0, 2.0, -0.5)
        // Add world position (1.0, 2.0, 3.0):
        // (5.0, 4.0, 2.5)
        val worldPoint = node.transformPointToWorld(localPoint)
        assertEquals(5.0f, worldPoint.x, 1e-4f)
        assertEquals(4.0f, worldPoint.y, 1e-4f)
        assertEquals(2.5f, worldPoint.z, 1e-4f)

        // Transform back from world to local
        val backToLocal = node.transformPointFromWorld(worldPoint)
        assertEquals(localPoint.x, backToLocal.x, 1e-4f)
        assertEquals(localPoint.y, backToLocal.y, 1e-4f)
        assertEquals(localPoint.z, backToLocal.z, 1e-4f)
    }

    @Test
    fun spatialNode_transformVectorToWorld_andFromWorld_withScale() {
        val node =
            SpatialNode(
                name = "test-node",
                attributes =
                    mapOf(
                        "ImpNodeWorldPosition" to floatArrayOf(10.0f, 20.0f, 30.0f),
                        "ImpNodeWorldRotation" to floatArrayOf(0.7071068f, 0.0f, 0.7071068f, 0.0f),
                        "ImpNodeWorldScale" to floatArrayOf(0.5f, 2.0f, 4.0f),
                    ),
            )

        val localVector = Vector3(1.0f, 1.0f, 1.0f)
        // Vectors ignore position offset; only scale and rotation apply:
        // (4.0, 2.0, -0.5)
        val worldVector = node.transformVectorToWorld(localVector)
        assertEquals(4.0f, worldVector.x, 1e-4f)
        assertEquals(2.0f, worldVector.y, 1e-4f)
        assertEquals(-0.5f, worldVector.z, 1e-4f)

        // Transform back from world to local
        val backToLocal = node.transformVectorFromWorld(worldVector)
        assertEquals(localVector.x, backToLocal.x, 1e-4f)
        assertEquals(localVector.y, backToLocal.y, 1e-4f)
        assertEquals(localVector.z, backToLocal.z, 1e-4f)
    }
